{
  "units": [
    {
      "quote_ref": "F001",
      "scope_refs": ["F000"],
      "kind": "prohibition",
      "meaning": "No driver shall use alcohol (as defined in § 382.107 of this subchapter) or be under the influence of alcohol within 4 hours before going on duty or operating, or having physical control of, a commercial motor vehicle."
    },
    {
      "quote_ref": "F002",
      "scope_refs": ["F000"],
      "kind": "prohibition",
      "meaning": "No driver shall use alcohol, be under the influence of alcohol, or have any measured alcohol concentration or detected presence of alcohol while on duty, operating, or in physical control of a commercial motor vehicle."
    },
    {
      "quote_ref": "F003",
      "scope_refs": ["F000"],
      "kind": "prohibition",
      "meaning": "No driver shall be on duty or operate a commercial motor vehicle while possessing wine of not less than 0.5% alcohol by volume, beer (as defined in 26 U.S.C. 5052(a)), or distilled spirits (as defined in 26 U.S.C. 5002(a)(8)), subject to specified shipment and passenger exceptions."
    },
    {
      "quote_ref": "F004",
      "scope_refs": ["F000", "F003"],
      "kind": "exception",
      "meaning": "The prohibition against possessing wine, beer, or distilled spirits while on duty or operating a commercial motor vehicle does not apply if the alcohol is manifested and transported as part of a shipment."
    },
    {
      "quote_ref": "F005",
      "scope_refs": ["F000", "F003"],
      "kind": "exception",
      "meaning": "The prohibition against possessing wine, beer, or distilled spirits while on duty or operating a commercial motor vehicle does not apply if the alcohol is possessed or used by bus passengers."
    },
    {
      "quote_ref": "F007",
      "scope_refs": ["F006"],
      "kind": "prohibition",
      "meaning": "No motor carrier shall require or permit a driver to violate any provision of paragraph (a) of 49 CFR 392.5."
    },
    {
      "quote_ref": "F008:F009",
      "scope_refs": ["F006"],
      "kind": "prohibition",
      "meaning": "No motor carrier shall require or permit a driver to be on duty or operate a commercial motor vehicle if, by the driver's general appearance or conduct or by other substantiating evidence, the driver appears to have used alcohol within the preceding 4 hours."
    },
    {
      "quote_ref": "F010",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "Any driver found to be in violation of paragraph (a) or paragraph (b) of 49 CFR 392.5 must be placed out of service immediately for a period of 24 hours."
    },
    {
      "quote_ref": "F011",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "The 24-hour out-of-service period commences upon issuance of an out-of-service order."
    },
    {
      "quote_ref": "F012",
      "scope_refs": [],
      "kind": "prohibition",
      "meaning": "No driver shall violate the terms of an out-of-service order issued under 49 CFR 392.5."
    },
    {
      "quote_ref": "F014",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "Any driver who is issued an out-of-service order under 49 CFR 392.5 must report its issuance to his/her employer within 24 hours."
    },
    {
      "quote_ref": "F015",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "Any driver issued an out-of-service order under 49 CFR 392.5 must report its issuance within 30 days to the designated State official of the licensing State, unless review is requested; if review is requested, the driver must report the order to that State official within 30 days of affirmation by the Division Administrator, the State Director for the geographical area, or the Administrator."
    },
    {
      "quote_ref": "F016",
      "scope_refs": [],
      "kind": "permission",
      "meaning": "A driver subject to an out-of-service order under 49 CFR 392.5 may petition for review by submitting a written petition within 10 days of order issuance to the Division Administrator or State Director for the geographical area, who may affirm or reverse the order; and any driver adversely affected by an order of the Regional Director of Motor Carriers may petition the Administrator for review under 49 CFR 386.13."
    }
  ]
}
